'use client'

import {
  cn,
  DismissableLayer,
  FocusScope,
  Portal,
  Presence,
  useControllableSignal,
  useRovingFocus,
  useSignals,
} from '@cascivo/core'
import { builtin, t } from '@cascivo/i18n'
import { useId } from 'react'
import type { ReactNode } from 'react'
import styles from './action-sheet.module.css'

export interface ActionSheetAction {
  /**
   * Stable identity, used as the React key. Without it the array index (or a repeatable
   * `label`) is the key, so inserting or reordering entries re-uses the wrong DOM node — the
   * defect `link-item-id-parity` exists to prevent, extended past link-shaped items on
   * 2026-08-22.
   */
  id?: string
  label: ReactNode
  onSelect: () => void
  /** Render in the destructive (danger) style. */
  destructive?: boolean
  disabled?: boolean
}

export interface ActionSheetProps {
  /** Controlled open state. */
  open?: boolean
  /** Initial open state for uncontrolled use. */
  defaultOpen?: boolean
  /** Called whenever the open state should change (selection, cancel, Escape, outside press). */
  onOpenChange?: (open: boolean) => void
  /** The choices presented, top to bottom. */
  actions: ActionSheetAction[]
  /** Optional heading shown above the actions; also labels the menu. */
  title?: ReactNode
  /** Optional supporting message under the title. */
  description?: ReactNode
  /**
   * When true, shows a cancel button below the actions.
   *
   * @defaultValue `true`
   * @see the component manifest
   */
  showCancel?: boolean
  labels?: { cancel?: string; label?: string }
  className?: string
}

/**
 * Bottom-rising sheet of discrete actions (iOS action-sheet pattern). Renders a
 * role="menu" of menuitems with vertical roving focus (Arrow keys, Home/End, wraps);
 * Escape and outside press dismiss it, and a separate Cancel button gives an explicit
 * non-destructive exit. Body scroll is not locked — the sheet is transient. Reuses the
 * overlay primitives and CSS-only slide; no animation library.
 */
export function ActionSheet({
  open,
  defaultOpen,
  onOpenChange,
  actions,
  title,
  description,
  showCancel = true,
  labels,
  className,
}: ActionSheetProps) {
  useSignals()
  const [isOpen, setOpen] = useControllableSignal<boolean>({
    value: open,
    defaultValue: defaultOpen ?? false,
    onChange: onOpenChange,
  })

  const roving = useRovingFocus({ orientation: 'vertical', loop: true })

  const titleId = useId()
  const descId = useId()
  const cancelLabel = labels?.cancel ?? t(builtin.actionSheet.cancel)
  const menuLabel = labels?.label ?? t(builtin.actionSheet.label)

  const select = (action: ActionSheetAction): void => {
    if (action.disabled) return
    action.onSelect()
    setOpen(false)
  }

  // Cancel is the last roving item so Arrow keys reach it.
  const cancelIndex = actions.length

  return (
    <Portal>
      <Presence present={isOpen}>
        <div className={styles['overlay']}>
          <DismissableLayer onDismiss={() => setOpen(false)}>
            <FocusScope trapped restoreFocus autoFocus>
              <div
                role="menu"
                aria-label={title ? undefined : menuLabel}
                aria-labelledby={title ? titleId : undefined}
                aria-describedby={description ? descId : undefined}
                className={cn(styles['sheet'], className)}
              >
                <div className={styles['group']}>
                  {(title || description) && (
                    <div className={styles['heading']} role="presentation">
                      {title && (
                        <p id={titleId} className={styles['title']}>
                          {title}
                        </p>
                      )}
                      {description && (
                        <p id={descId} className={styles['description']}>
                          {description}
                        </p>
                      )}
                    </div>
                  )}
                  {actions.map((action, index) => {
                    const itemProps = roving.getItemProps(index)
                    return (
                      <button
                        key={action.id ?? index}
                        ref={itemProps.ref as React.Ref<HTMLButtonElement>}
                        type="button"
                        role="menuitem"
                        tabIndex={itemProps.tabIndex}
                        aria-disabled={action.disabled || undefined}
                        data-destructive={action.destructive ? '' : undefined}
                        className={styles['item']}
                        onKeyDown={itemProps.onKeyDown}
                        onFocus={itemProps.onFocus}
                        onClick={() => select(action)}
                      >
                        {action.label}
                      </button>
                    )
                  })}
                </div>
                {showCancel && (
                  <div className={styles['group']}>
                    {(() => {
                      const itemProps = roving.getItemProps(cancelIndex)
                      return (
                        <button
                          ref={itemProps.ref as React.Ref<HTMLButtonElement>}
                          type="button"
                          role="menuitem"
                          tabIndex={itemProps.tabIndex}
                          className={cn(styles['item'], styles['cancel'])}
                          onKeyDown={itemProps.onKeyDown}
                          onFocus={itemProps.onFocus}
                          onClick={() => setOpen(false)}
                        >
                          {cancelLabel}
                        </button>
                      )
                    })()}
                  </div>
                )}
              </div>
            </FocusScope>
          </DismissableLayer>
        </div>
      </Presence>
    </Portal>
  )
}

@layer cascivo.component {
  .overlay {
    position: fixed;
    inset: 0;
    z-index: var(--cascivo-z-overlay, 50);
    display: flex;
    flex-direction: column;
    justify-content: flex-end;
    align-items: center;
    padding: var(--cascivo-space-3);
    padding-block-end: calc(var(--cascivo-space-3) + env(safe-area-inset-bottom, 0px));
    background-color: rgb(0 0 0 / 0.4);
    opacity: 1;
    transition: opacity var(--cascivo-motion-enter);

    &[data-state='closed'] {
      opacity: 0;
      transition: opacity var(--cascivo-motion-exit);
    }

    @starting-style {
      &[data-state='open'] {
        opacity: 0;
      }
    }
  }

  .sheet {
    display: flex;
    flex-direction: column;
    gap: var(--cascivo-space-2);
    inline-size: 100%;
    max-inline-size: 32rem;
    translate: 0 0;
    transition: translate var(--cascivo-motion-enter);

    .overlay[data-state='closed'] & {
      translate: 0 100%;
      transition: translate var(--cascivo-motion-exit);
    }
  }

  /* Slide up from off-screen on first mount. */
  @starting-style {
    .overlay[data-state='open'] .sheet {
      translate: 0 100%;
    }
  }

  .group {
    display: flex;
    flex-direction: column;
    background: var(--cascivo-color-surface);
    border: 1px solid var(--cascivo-color-border);
    border-radius: var(--cascivo-radius-overlay);
    box-shadow: var(--cascivo-shadow-overlay);
    overflow: hidden;
  }

  .heading {
    padding: var(--cascivo-space-4) var(--cascivo-space-6);
    text-align: center;
    border-block-end: 1px solid var(--cascivo-color-border);
  }

  .title {
    margin: 0;
    font-size: var(--cascivo-text-sm);
    font-weight: var(--cascivo-font-semibold);
    color: var(--cascivo-color-text);
  }

  .description {
    margin: var(--cascivo-space-1) 0 0;
    font-size: var(--cascivo-text-sm);
    color: var(--cascivo-color-text-subtle);
  }

  .item {
    display: flex;
    align-items: center;
    justify-content: center;
    inline-size: 100%;
    min-block-size: 3rem; /* 48px — already past the 44px coarse touch target */
    padding: var(--cascivo-space-3) var(--cascivo-space-6);
    font-size: var(--cascivo-text-base);
    color: var(--cascivo-color-accent-text);
    background: transparent;
    border: none;
    cursor: pointer;
    transition: background-color var(--cascivo-duration-150) var(--cascivo-ease-out);

    & + .item {
      border-block-start: 1px solid var(--cascivo-color-border);
    }

    &:hover {
      background-color: var(--cascivo-color-bg-subtle);
    }

    &:focus-visible {
      outline: none;
      box-shadow: var(--cascivo-focus-ring);
      /* Keep the ring above sibling borders. */
      position: relative;
      z-index: 1;
    }

    &[aria-disabled='true'] {
      color: var(--cascivo-color-text-muted);
      cursor: not-allowed;
    }

    &[data-destructive] {
      color: var(--cascivo-color-destructive);
    }
  }

  .cancel {
    font-weight: var(--cascivo-font-semibold);
    color: var(--cascivo-color-text);
  }

  @media (prefers-reduced-motion: reduce) {
    .sheet {
      transition: none;
    }
  }
}

import type { ComponentMeta } from '@cascivo/core'

export const meta: ComponentMeta = {
  name: 'ActionSheet',
  description:
    'Bottom-rising sheet of discrete actions (iOS action-sheet pattern) with a Cancel button',
  category: 'overlay',
  clientJs: 'required',
  states: ['open', 'closed'],
  variants: [],
  sizes: [],
  props: [
    {
      name: 'open',
      description: 'Whether the component is open (controlled).',
      type: 'boolean',
      required: false,
    },
    {
      name: 'defaultOpen',
      description: 'Whether the component is open on first render (uncontrolled).',
      type: 'boolean',
      required: false,
    },
    {
      name: 'onOpenChange',
      description: 'Called with the next open state when it changes.',
      type: '(open: boolean) => void',
      required: false,
    },
    {
      name: 'actions',
      type: 'ActionSheetAction[]',
      required: true,
      description: 'Choices, each with a label, onSelect, and optional destructive/disabled flags',
    },
    {
      name: 'title',
      description: 'Title text for the component.',
      type: 'React.ReactNode',
      required: false,
    },
    {
      name: 'description',
      description: 'Supporting description text.',
      type: 'React.ReactNode',
      required: false,
    },
    {
      name: 'showCancel',
      description: 'When true, shows a cancel button below the actions.',
      type: 'boolean',
      required: false,
      default: 'true',
    },
    {
      name: 'labels',
      description: 'Overrides for the component’s user-visible strings (i18n).',
      type: '{ cancel?: string; label?: string }',
      required: false,
    },
    {
      name: 'className',
      description: 'Additional CSS class names merged onto the root element.',
      type: 'string',
      required: false,
    },
  ],
  tokens: [
    '--cascivo-color-accent-text',
    '--cascivo-color-surface',
    '--cascivo-color-border',
    '--cascivo-color-destructive',
    '--cascivo-color-text',
    '--cascivo-color-text-subtle',
    '--cascivo-color-text-muted',
    '--cascivo-radius-overlay',
    '--cascivo-shadow-overlay',
    '--cascivo-motion-enter',
    '--cascivo-motion-exit',
    '--cascivo-z-overlay',
  ],
  accessibility: {
    role: 'menu',
    wcag: '2.2-AA',
    keyboard: ['ArrowUp', 'ArrowDown', 'Home', 'End', 'Enter', 'Space', 'Escape'],
  },
  examples: [
    {
      title: 'Basic',
      code: `<ActionSheet
  open={isOpen}
  onOpenChange={setIsOpen}
  title="Share photo"
  actions={[
    { label: 'Copy link', onSelect: copyLink },
    { label: 'Delete', onSelect: remove, destructive: true },
  ]}
/>`,
    },
    {
      title: 'Without cancel button',
      code: '<ActionSheet defaultOpen showCancel={false} actions={[{ label: "Archive", onSelect: archive }]} />',
      description: 'Escape and outside press still dismiss the sheet.',
    },
  ],
  dependencies: ['@cascivo/core', '@cascivo/i18n'],
  tags: ['overlay', 'action-sheet', 'menu', 'mobile', 'sheet'],
  intent: {
    whenToUse: [
      'A short list of discrete actions on a touch surface, rising from the bottom',
      'Confirming or choosing among a few operations (e.g. Share, Edit, Delete) on mobile',
      'A mobile-first alternative to an anchored dropdown menu when there is no trigger anchor',
    ],
    whenNotToUse: [
      'A single yes/no confirmation — use AlertDialog',
      'A form or scrollable content — use BottomSheet or Sheet',
      'A menu anchored to a trigger on desktop — use Menu or Dropdown',
    ],
    antiPatterns: [
      {
        bad: '<ActionSheet actions={[{ label: "OK", onSelect }]} />',
        good: '<AlertDialog title="Delete item?" />',
        why: 'A one-action sheet is a confirmation; AlertDialog states the decision clearly',
      },
    ],
    related: [
      {
        name: 'BottomSheet',
        relationship: 'alternative',
        reason:
          'Use BottomSheet for rich/resizable content; ActionSheet is a fixed list of actions',
      },
      {
        name: 'Menu',
        relationship: 'alternative',
        reason: 'Use Menu for a trigger-anchored dropdown on pointer-first surfaces',
      },
    ],
    a11yRationale:
      'Renders role="menu" with role="menuitem" buttons under vertical roving focus (Arrow keys, Home/End, wrapping). The title labels the menu via aria-labelledby (or a built-in label otherwise) and the description via aria-describedby. FocusScope traps and restores focus; DismissableLayer handles Escape and outside-pointer dismissal; a separate Cancel button provides an explicit non-destructive exit.',
    flexibility: [
      {
        area: 'actions',
        level: 'flexible',
        note: 'Any number of actions; each may be destructive or disabled',
      },
      {
        area: 'open state',
        level: 'flexible',
        note: 'Controlled (open/onOpenChange) or uncontrolled (defaultOpen)',
      },
      {
        area: 'cancel',
        level: 'flexible',
        note: 'showCancel toggles the separate Cancel button (Escape/outside press still dismiss)',
      },
    ],
  },
}
